<script setup lang="ts">
import { AlarmClock, CheckCircle2, Clock3, Play, Plus, Save, Trash2, X } from '@lucide/vue';

defineProps<{ modelValue: boolean }>();
const emit = defineEmits(['update:modelValue', 'created']);
const config = useRuntimeConfig();
const { token } = useWorkspaceSession();
const templates = ref<any[]>([]), reminders = ref<any[]>([]), team = ref<any[]>([]);
const tab = ref('templates'), saving = ref(false), error = ref('');
const draft = reactive<any>({ name: '', title: '', description: '', priority: 'MEDIUM', labels: '', estimateMinutes: 60, dueInHours: 24, reminderBeforeMin: 60, defaultAssigneeId: '' });
const headers = computed(() => ({ Authorization: `Bearer ${token.value}` }));
const priorityLabels: any = { LOW: 'Низкий', MEDIUM: 'Обычный', HIGH: 'Высокий', CRITICAL: 'Критичный' };
function person(user: any) { return [user?.firstName, user?.lastName].filter(Boolean).join(' ') || user?.email || 'Не назначен'; }
async function load() { [templates.value, reminders.value, team.value] = await Promise.all([$fetch<any[]>('/crm/task-templates', { baseURL: config.public.apiBase, headers: headers.value }), $fetch<any[]>('/crm/reminders', { baseURL: config.public.apiBase, headers: headers.value }), $fetch<any[]>('/crm/team', { baseURL: config.public.apiBase, headers: headers.value })]); }
async function createTemplate() { saving.value = true; error.value = ''; try { await $fetch('/crm/task-templates', { baseURL: config.public.apiBase, method: 'POST', headers: headers.value, body: { ...draft, labels: String(draft.labels).split(',').map(item => item.trim()).filter(Boolean), estimateMinutes: Number(draft.estimateMinutes), dueInHours: Number(draft.dueInHours), reminderBeforeMin: Number(draft.reminderBeforeMin), defaultAssigneeId: draft.defaultAssigneeId || undefined } }); Object.assign(draft, { name: '', title: '', description: '', priority: 'MEDIUM', labels: '', estimateMinutes: 60, dueInHours: 24, reminderBeforeMin: 60, defaultAssigneeId: '' }); await load(); } catch (exception: any) { error.value = exception?.data?.message || 'Не удалось создать шаблон'; } finally { saving.value = false; } }
async function launch(template: any) { await $fetch(`/crm/task-templates/${template.id}/create-task`, { baseURL: config.public.apiBase, method: 'POST', headers: headers.value, body: {} }); emit('created'); emit('update:modelValue', false); }
async function archive(template: any) { await $fetch(`/crm/task-templates/${template.id}`, { baseURL: config.public.apiBase, method: 'DELETE', headers: headers.value }); await load(); }
async function dismiss(reminder: any) { await $fetch(`/crm/reminders/${reminder.id}/dismiss`, { baseURL: config.public.apiBase, method: 'POST', headers: headers.value }); await load(); }
onMounted(load);
</script>

<template><Teleport to="body"><div v-if="modelValue" class="automation-backdrop" @click.self="emit('update:modelValue',false)"><section class="automation"><header><div><p>CRM / АВТОМАТИЗАЦИЯ</p><h2>Шаблоны и напоминания</h2><span>Повторяемые сценарии работы команды</span></div><button @click="emit('update:modelValue',false)"><X :size="18"/></button></header><nav><button :class="{active:tab==='templates'}" @click="tab='templates'">Шаблоны задач <em>{{templates.length}}</em></button><button :class="{active:tab==='reminders'}" @click="tab='reminders'">Активные напоминания <em>{{reminders.length}}</em></button></nav>
  <main v-if="tab==='templates'"><section class="template-list"><article v-for="item in templates"><i><Clock3 :size="17"/></i><span><b>{{item.name}}</b><strong>{{item.title}}</strong><small>{{priorityLabels[item.priority]}} · срок через {{item.dueInHours||'—'}} ч · напомнить за {{item.reminderBeforeMin||0}} мин</small><em v-if="item.defaultAssignee">{{person(item.defaultAssignee)}}</em></span><button title="Создать задачу" @click="launch(item)"><Play :size="14"/></button><button class="delete" title="Архивировать шаблон" @click="archive(item)"><Trash2 :size="14"/></button></article><p v-if="!templates.length">Шаблонов пока нет</p></section>
    <form @submit.prevent="createTemplate"><h3><Plus :size="16"/>Новый шаблон</h3><div class="two"><label>Название шаблона<input v-model="draft.name" required/></label><label>Название задачи<input v-model="draft.title" required/></label></div><label>Описание<textarea v-model="draft.description" rows="3"/></label><div class="three"><label>Приоритет<select v-model="draft.priority"><option v-for="(label,key) in priorityLabels" :value="key">{{label}}</option></select></label><label>Срок через, часов<input v-model.number="draft.dueInHours" type="number" min="1"/></label><label>Напомнить за, минут<input v-model.number="draft.reminderBeforeMin" type="number" min="0"/></label></div><div class="two"><label>Ответственный по умолчанию<select v-model="draft.defaultAssigneeId"><option value="">Создатель задачи</option><option v-for="member in team" :value="member.id">{{person(member)}}</option></select></label><label>Метки через запятую<input v-model="draft.labels" placeholder="звонок, документы"/></label></div><p v-if="error" class="error">{{error}}</p><button class="save" :disabled="saving"><Save :size="14"/>{{saving?'Сохраняем…':'Сохранить шаблон'}}</button></form>
  </main><main v-else class="reminders"><article v-for="item in reminders"><i><AlarmClock :size="18"/></i><span><b>{{item.task.title}}</b><small>Срок {{item.task.dueDate?new Date(item.task.dueDate).toLocaleString('ru-RU'):'не задан'}}</small></span><button @click="dismiss(item)"><CheckCircle2 :size="15"/>Выполнено</button></article><p v-if="!reminders.length">Сейчас активных напоминаний нет</p></main>
</section></div></Teleport></template>

<style scoped>
.automation-backdrop{position:fixed;z-index:840;inset:0;background:#0006;font-family:var(--sb-font);color:var(--sb-ink)}.automation{position:absolute;right:0;top:0;bottom:0;width:min(840px,calc(100vw - 72px));background:#f4f5f7;display:grid;grid-template-rows:88px 50px 1fr}.automation>header{background:#fff;border-bottom:1px solid var(--sb-line);padding:0 25px;display:flex;align-items:center;justify-content:space-between}.automation>header p{margin:0 0 7px;font-size:8px;color:var(--sb-coral);letter-spacing:.16em}.automation>header h2{font-size:23px;margin:0}.automation>header span{font-size:9px;color:#888}.automation>header button{border:0;background:none}.automation>nav{display:flex;background:#fff;border-bottom:1px solid var(--sb-line);padding:0 20px}.automation>nav button{border:0;background:#fff;padding:0 15px;font:9px var(--sb-font);display:flex;align-items:center;gap:7px}.automation>nav button.active{border-bottom:2px solid var(--sb-coral);color:var(--sb-coral)}.automation>nav em{min-width:18px;height:18px;border-radius:10px;background:#eee;display:grid;place-items:center;font-style:normal;font-size:7px}.automation>main{padding:20px;overflow:auto;display:grid;gap:14px;align-content:start}.template-list,form,.reminders article{background:#fff;border:1px solid var(--sb-line)}.template-list article{min-height:72px;padding:10px 13px;border-top:1px solid #eee;display:grid;grid-template-columns:38px 1fr 34px 34px;gap:9px;align-items:center}.template-list article:first-child{border:0}.template-list article>i{width:36px;height:36px;background:#fff0ed;color:var(--sb-coral);display:grid;place-items:center}.template-list article>span{display:grid;gap:3px}.template-list article b{font-size:8px;color:var(--sb-coral)}.template-list article strong{font-size:10px}.template-list article small,.template-list article em{font-size:7px;color:#888;font-style:normal}.template-list button{width:32px;height:32px;border:0;background:#1d1e22;color:#fff}.template-list .delete{background:#fff0ed;color:#a84538}.template-list>p,.reminders>p{font-size:9px;color:#888;padding:20px}form{padding:18px;display:grid;gap:11px}form h3{font-size:13px;margin:0 0 5px;display:flex;align-items:center;gap:7px}.two,.three{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.three{grid-template-columns:repeat(3,1fr)}form label{display:grid;gap:5px;font-size:8px;color:#73767c}form input,form textarea,form select{border:1px solid var(--sb-line);padding:9px;font:9px var(--sb-font);background:#fff;box-sizing:border-box;width:100%}form input,form select{height:37px}.save{height:37px;border:0;background:#1d1e22;color:#fff;justify-self:end;padding:0 13px;display:flex;align-items:center;gap:6px;font:8px var(--sb-font)}.error{font-size:8px;color:#a84538}.reminders article{min-height:64px;padding:10px 14px;display:grid;grid-template-columns:35px 1fr auto;gap:10px;align-items:center}.reminders article>i{color:var(--sb-coral)}.reminders article span{display:grid;gap:4px}.reminders article b{font-size:10px}.reminders article small{font-size:8px;color:#888}.reminders article button{height:33px;border:0;background:#edf7f1;color:#267655;padding:0 10px;display:flex;align-items:center;gap:5px;font:8px var(--sb-font)}@media(max-width:650px){.automation{width:100vw}.two,.three{grid-template-columns:1fr}}
</style>
